// vlxd-responsive-correction-v1: explicit labels avoid overlap on mobile/web.
Widget _correctionInput(
  TextEditingController controller,
  String label, {
  bool decimalNumber = false,
  bool moneyInput = false,
  String? hintText,
}) => Padding(
  padding: const EdgeInsets.only(bottom: 12),
  child: Column(
    crossAxisAlignment: CrossAxisAlignment.start,
    children: [
      Text(label, style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w700)),
      const SizedBox(height: 6),
      TextField(
        controller: controller,
        keyboardType: moneyInput
            ? TextInputType.number
            : decimalNumber
                ? const TextInputType.numberWithOptions(decimal: true)
                : TextInputType.text,
        inputFormatters: moneyInput ? [const MoneyInputFormatter()] : null,
        decoration: InputDecoration(
          hintText: hintText,
          isDense: true,
          contentPadding: const EdgeInsets.symmetric(horizontal: 12, vertical: 12),
        ),
      ),
    ],
  ),
);

